2	import { cn } from "@/lib/utils";
3	import { extractMentionUsernames } from "@/utils/remark-plugins/remark-mention";
4	import { MemoMarkdownRenderer } from "./MemoMarkdownRenderer";
5	import { useResolvedMentionUsernames } from "./MentionResolutionContext";
6	import type { MemoContentProps } from "./types";
7	
8	// Stateless markdown renderer. Truncation is not this component's concern — compact cards
9	// are bounded by ClampedSection around the whole memo body; `compact` here only informs
10	// the renderer (e.g. footnote links navigate to the detail page instead of scrolling,
11	// since a collapsed card may hide the target).
12	const MemoContent = (props: MemoContentProps) => {
13	  const { className, contentClassName, content, onClick, onDoubleClick } = props;
14	  const mentionUsernames = useMemo(() => extractMentionUsernames(content), [content]);
15	  const resolvedMentionUsernames = useResolvedMentionUsernames(mentionUsernames);
16	
17	  return (
18	    <div className={`w-full flex flex-col justify-start items-start text-foreground ${className || ""}`}>
19	      <div
20	        data-memo-content
21	        className={cn(
22	          "relative w-full max-w-full wrap-break-word text-base leading-6",
23	          "[&>*:last-child]:mb-0",
24	          "[&_.katex-display]:max-w-full",
25	          "[&_.katex-display]:overflow-x-auto",
26	          "[&_.katex-display]:overflow-y-hidden",
27	          // Footnotes: quiet GitHub-style footer — thin separator, smaller muted text, unobtrusive links.
28	          "[&_.footnotes]:mt-4 [&_.footnotes]:border-t [&_.footnotes]:border-border [&_.footnotes]:pt-2",
29	          "[&_.footnotes]:text-sm [&_.footnotes]:text-muted-foreground",
30	          // GitHub renders footnote ref/backref links without an underline (underline on hover only).
31	          "[&_[data-footnote-ref]]:no-underline [&_[data-footnote-ref]:hover]:underline",
32	          "[&_.data-footnote-backref]:no-underline [&_.data-footnote-backref:hover]:underline",
33	          contentClassName,
34	        )}
35	        onMouseUp={onClick}
36	        onDoubleClick={onDoubleClick}
37	      >
38	        <MemoMarkdownRenderer
39	          content={content}
40	          resolvedMentionUsernames={resolvedMentionUsernames}
41	          memoName={props.memoName}
42	          compact={Boolean(props.compact)}
43	        />
44	      </div>
45	    </div>
46	  );
47	};
48	
49	export default memo(MemoContent);
